() => {
  const [filterVal, setFilterVal] = useState<string>('')
  const handleChange: ChangeEventHandler<HTMLInputElement> = (e) => {
    setFilterVal(e.currentTarget.value)
  }
  const customFilterFn = (item: Datum) => item.text.includes(filterVal)
  return (
    <form className={classes.FormPadding}>
      <FormControl>
        <FormControl.Label id="autocompleteLabel">
          Default label
        </FormControl.Label>
        <Autocomplete>
          <Autocomplete.Input onChange={handleChange} />
          <Autocomplete.Overlay>
            <Autocomplete.Menu
              items={items}
              selectedItemIds={[]}
              filterFn={customFilterFn}
              aria-labelledby="autocompleteLabel"
            />
          </Autocomplete.Overlay>
        </Autocomplete>
        <FormControl.Caption>
          Items in dropdown are filtered if their text has no part that matches
          the input value
        </FormControl.Caption>
      </FormControl>
    </form>
  )
}

() => {
  const [selectedItemIds, setSelectedItemIds] = useState<Array<string>>([])
  const isItemSelected = (itemId: string) => selectedItemIds.includes(itemId)
  const onSelectedChange = (newlySelectedItems: Datum | Datum[]) => {
    if (!Array.isArray(newlySelectedItems)) {
      return
    }
    setSelectedItemIds(newlySelectedItems.map((item) => item.id))
  }
  const customSortFn = (itemIdA: string, itemIdB: string) =>
    isItemSelected(itemIdA) === isItemSelected(itemIdB)
      ? 0
      : isItemSelected(itemIdA)
        ? 1
        : -1
  return (
    <form className={classes.FormPadding}>
      <FormControl>
        <FormControl.Label id="autocompleteLabel">
          Default label
        </FormControl.Label>
        <Autocomplete>
          <Autocomplete.Input />
          <Autocomplete.Overlay>
            <Autocomplete.Menu
              items={items}
              selectedItemIds={selectedItemIds}
              onSelectedChange={onSelectedChange}
              sortOnCloseFn={customSortFn}
              aria-labelledby="autocompleteLabel"
            />
          </Autocomplete.Overlay>
        </Autocomplete>
        <FormControl.Caption>
          When the dropdown closes, selected items are sorted to the end
        </FormControl.Caption>
      </FormControl>
    </form>
  )
}

