(args: FormControlArgs<AutocompleteArgs>) => {
  const { parentArgs, labelArgs, captionArgs, validationArgs } =
    getFormControlArgsByChildComponent(args)
  const { menuArgs, overlayArgs, textInputArgs } = getArgsByChildComponent(args)
  const [loadedItems, setLoadedItems] = useState<Datum[]>([])
  const onOpenChange = (isOpen: boolean) => {
    if (isOpen) {
      setTimeout(() => {
        setLoadedItems(items)
      }, 1500)
    }
  }
  return (
    <form className={classes.FormPadding}>
      <FormControl {...parentArgs}>
        <FormControl.Label id="autocompleteLabel" {...labelArgs} />
        <Autocomplete>
          <Autocomplete.Input
            {...textInputArgs}
            size={textInputArgs.inputSize}
          />
          <Autocomplete.Overlay {...overlayArgs}>
            <Autocomplete.Menu
              items={loadedItems}
              selectedItemIds={[]}
              onOpenChange={onOpenChange}
              aria-labelledby="autocompleteLabel"
              {...menuArgs}
              loading={loadedItems.length === 0}
            />
          </Autocomplete.Overlay>
        </Autocomplete>
        {captionArgs.children && <FormControl.Caption {...captionArgs} />}
        {validationArgs.children && validationArgs.variant && (
          <FormControl.Validation
            {...validationArgs}
            variant={validationArgs.variant}
          />
        )}
      </FormControl>
    </form>
  )
}

