() => {
  const scrollContainerRef = useRef<HTMLElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const triggerRef = useRef<HTMLButtonElement>(null)
  const [isOpen, setIsOpen] = useState(false)
  const [selectedItem, setSelectedItem] = useState<Datum>()
  const handleOpen = () => {
    setIsOpen(true)
    inputRef.current && inputRef.current.focus()
  }
  const selectChange = (item: Datum[] | Datum) => {
    setIsOpen(false)
    if (Array.isArray(item) && item.length) setSelectedItem(item[0])
    triggerRef.current?.focus()
  }
  return (
    <form className={classes.FormPadding}>
      <span id="selected-item-status">
        Selected item: {selectedItem ? selectedItem.text : 'none'}
      </span>

      <AnchoredOverlay
        open={isOpen}
        onOpen={handleOpen}
        onClose={() => setIsOpen(false)}
        width="large"
        focusTrapSettings={{
          initialFocusRef: inputRef,
        }}
        side="inside-top"
        anchorRef={triggerRef}
        renderAnchor={(props) => (
          <Button {...props} aria-describedby="selected-item-status">
            open overlay
          </Button>
        )}
        preventOverflow={false}
      >
        <Autocomplete>
          <div className={classes.OverlayFlexCol}>
            <div className={classes.OverlayInputBar}>
              <Autocomplete.Input
                ref={inputRef}
                className={classes.OverlayInput}
                block
                aria-label="Search"
              />
            </div>
            <div
              ref={scrollContainerRef as RefObject<HTMLDivElement>}
              className={classes.OverlayScroll}
            >
              <Autocomplete.Menu
                items={items}
                selectedItemIds={[]}
                customScrollContainerRef={scrollContainerRef}
                aria-labelledby="autocompleteLabel"
                onSelectedChange={selectChange}
              />
            </div>
          </div>
        </Autocomplete>
      </AnchoredOverlay>
    </form>
  )
}

() => {
  const outerContainerRef = useRef<HTMLDivElement>(null)
  const [mounted, setMounted] = useState(false)
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  useEffect(() => {
    if (outerContainerRef.current instanceof HTMLElement) {
      registerPortalRoot(outerContainerRef.current, 'outerContainer')
      // eslint-disable-next-line react-you-might-not-need-an-effect/no-chain-state-updates
      setMounted(true)
    }
  }, [isDialogOpen])
  return (
    <>
      <Button onClick={() => setIsDialogOpen(true)}>Show dialog</Button>
      <Dialog
        aria-label="Dialog with autocomplete"
        id="dialog-with-autocomplete"
        isOpen={isDialogOpen}
        onDismiss={() => setIsDialogOpen(false)}
      >
        <div ref={outerContainerRef}>
          <form className={classes.FormPadding}>
            {mounted ? (
              <FormControl>
                <FormControl.Label id="autocompleteLabel">
                  Default label
                </FormControl.Label>
                <Autocomplete>
                  <Autocomplete.Input data-testid="autocompleteInput" />
                  <Autocomplete.Overlay portalContainerName="outerContainer">
                    <Autocomplete.Menu
                      items={items}
                      selectedItemIds={[]}
                      aria-labelledby="autocompleteLabel"
                    />
                  </Autocomplete.Overlay>
                </Autocomplete>
              </FormControl>
            ) : null}
          </form>
        </div>
      </Dialog>
      <p>
        The Autocomplete.Overlay is portalled to a div inside the Dialog to
        ensure it appears above the dialog in the stacking context.
      </p>
    </>
  )
}
